59	  });
60	
61	  it("does not escalate comment creation, which needs the member role", () => {
62	    expect(can(viewer, "comment:create", comment(ALICE))).toBe(false);
63	  });
64	
65	  it("lets a recipient manage their own notification", () => {
66	    const own: PermissionResource = {
67	      kind: "notification",
68	      orgId: ORG_A,
69	      recipientId: ALICE,
