71	    const other: PermissionResource = {
72	      kind: "notification",
73	      orgId: ORG_A,
74	      recipientId: BOB,
75	    };
76	    // `notification:manage` is a viewer action anyway, so both pass by role.
77	    expect(can(viewer, "notification:manage", own)).toBe(true);
78	    expect(can(viewer, "notification:manage", other)).toBe(true);
79	  });
80	
81	  it("does not escalate a project action for the project lead", () => {
82	    const led: PermissionResource = {
83	      kind: "project",
84	      orgId: ORG_A,
85	      projectId: PROJECT,
86	      visibility: "org",
87	      leadId: ALICE,
88	    };
89	    // `project:archive` is not in the escalation list, so the lead still needs admin.
90	    expect(can(viewer, "project:archive", led)).toBe(false);
91	    expect(can(makeActor({ role: "admin" }), "project:archive", led)).toBe(true);
92	  });
93	
94	  it("does not let a member escalate their own role", () => {
95	    const self: PermissionResource = {
96	      kind: "member",
97	      orgId: ORG_A,
98	      memberId: "01HZZZMMMMMMMMMMMMMMMMMMMM" as MemberId,
99	      targetUserId: ALICE,
100	      targetRole: "member",
101	    };
102	    expect(can(makeActor({ role: "member" }), "member:update_role", self)).toBe(false);
103	  });
104	
105	  it("keeps ownership subordinate to the tenant boundary", () => {
106	    const foreignActor = makeActor({ role: "viewer", userId: ALICE, orgId: ORG_A });
107	    const foreignIssue: PermissionResource = {
108	      ...issue(ALICE, ALICE),
