125	      expect.unreachable("assertCan should have thrown");
126	    } catch (error) {
127	      const denied = error as PermissionDeniedError;
128	      expect(denied.code).toBe("forbidden");
129	      expect(denied.action).toBe("issue:update");
130	      expect(denied.decision.reason).toBe("denied_by_role");
131	    }
132	  });
