51	/**
52	 * Creates one organization with a member in every role and a single project.
53	 * `plan` decides which quotas apply — the free plan's three seats is what the
54	 * invite-limit test leans on.
55	 */
56	export async function createTenant(
57	  slug: string,
58	  plan: PlanId = "growth",
59	): Promise<Tenant> {
60	  const owner = await userRepo.insertUser({
61	    email: `owner@${slug}.test`,
62	    name: `${slug} owner`,
63	    passwordHash: "seed",
64	  });
65	
66	  const org = await orgRepo.insertOrg(
67	    { name: `${slug} inc`, slug, plan },
68	    owner.id,
69	  );
70	
71	  await subscriptionRepo.insertSubscription(org.id, plan, "monthly");
72	
73	  const userIds: Partial<Record<Role, UserId>> = {};
74	  const actors: Partial<Record<Role, Actor>> = {};
75	
76	  for (const role of ROLES) {
77	    const user =
78	      role === "owner"
79	        ? owner
80	        : await userRepo.insertUser({
81	            email: `${role}@${slug}.test`,
82	            name: `${slug} ${role}`,
83	            passwordHash: "seed",
84	          });
85	
86	    await memberRepo.insertMember(org.id, user.id, role, null);
87	
88	    userIds[role] = user.id;
89	    actors[role] = { userId: user.id, orgId: org.id, role };
90	  }
91	
92	  const project = await projectRepo.insertProject({
93	    orgId: org.id,
94	    name: `${slug} platform`,
95	    slug: "platform",
96	    key: "PLAT",
97	    description: null,
98	    visibility: "org",
99	    leadId: owner.id,
100	    color: "#6366f1",
101	    targetDate: null,
102	  });
103	
104	  return {
105	    org,
106	    project,
107	    actors: actors as Readonly<Record<Role, Actor>>,
108	    userIds: userIds as Readonly<Record<Role, UserId>>,
109	  };
110	}
111	
112	/** Minimal `CreateIssueInput` with the schema's defaults already applied. */
113	export function issueInput(
114	  orgId: OrgId,
115	  projectId: Project["id"],
116	  overrides: Partial<{
117	    title: string;
118	    assigneeId: UserId | null;
119	    dueAt: string | null;
120	  }> = {},
121	) {
122	  return {
123	    orgId,
124	    projectId,
125	    title: overrides.title ?? "Ship the thing",
126	    description: null,
127	    status: "backlog" as const,
128	    priority: "none" as const,
129	    assigneeId: (overrides.assigneeId ?? null) as UserId | null,
130	    parentId: null,
131	    estimate: null,
132	    dueAt: (overrides.dueAt ?? null) as never,
133	    labelIds: [],
134	  };
135	}
